acid_rain_register_aftermath_humanitarian_pressure = {
	if = {
		limit = {
			check_variable = { var = acid_rain_state_aftermath_tier value = constant:acid_rain_runtime.two compare = greater_than_or_equals }
			OR = {
				NOT = { has_variable = acid_rain_humanitarian_tier_registered }
				check_variable = { var = acid_rain_humanitarian_tier_registered value = acid_rain_state_aftermath_tier compare = less_than }
			}
		}
		set_temp_variable = { acid_rain_humanitarian_amount = state_population_k }
		multiply_temp_variable = { acid_rain_humanitarian_amount = constant:acid_rain_humanitarian.people_per_k }
		if = {
			limit = { check_variable = { var = acid_rain_state_aftermath_tier value = constant:acid_rain_aftermath.tier_max compare = greater_than_or_equals } }
			multiply_temp_variable = { acid_rain_humanitarian_amount = constant:acid_rain_humanitarian.aftermath_tier_three_share }
		}
		else = { multiply_temp_variable = { acid_rain_humanitarian_amount = constant:acid_rain_humanitarian.aftermath_tier_two_share } }
		round_temp_variable = acid_rain_humanitarian_amount
		set_temp_variable = { acid_rain_humanitarian_kind = constant:acid_rain_humanitarian.kind_aftermath }
		set_temp_variable = { acid_rain_humanitarian_revision = acid_rain_state_aftermath_tier }
		set_temp_variable = { acid_rain_humanitarian_result = constant:acid_rain_aftermath.zero }
		acid_rain_register_humanitarian_pressure = yes
		if = {
			limit = { check_variable = { var = acid_rain_humanitarian_result value = constant:humanitarian_runtime.one compare = equals } }
			set_variable = { acid_rain_humanitarian_tier_registered = acid_rain_state_aftermath_tier }
		}
	}
}
